import { logger } from "./logger";

export interface Rendition {
  bandwidth: number;
  resolution: string;
  uri: string;
}

export interface PlaybackManifest {
  assetId: string;
  durationSec: number;
  renditions: Rendition[];
}

export class OriginTimeoutError extends Error {
  constructor(public readonly assetId: string, public readonly afterMs: number) {
    super(`origin did not respond for ${assetId} within ${afterMs}ms`);
  }
}

export class OriginClient {
  constructor(
    private readonly baseUrl: string,
    private readonly timeoutMs: number = 2500,
  ) {}

  async fetchManifest(assetId: string): Promise<PlaybackManifest> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), this.timeoutMs);
    const started = Date.now();
    try {
      const res = await fetch(`${this.baseUrl}/assets/${encodeURIComponent(assetId)}/manifest`, {
        signal: controller.signal,
        headers: { accept: "application/json" },
      });
      clearTimeout(timer);
      if (!res.ok) {
        throw new Error(`origin returned ${res.status} for ${assetId}`);
      }
      const body = (await res.json()) as PlaybackManifest;
      logger.info("manifest fetched", { assetId, ms: Date.now() - started });
      return body;
    } catch (err) {
      if ((err as Error).name === "AbortError") {
        throw new OriginTimeoutError(assetId, this.timeoutMs);
      }
      throw err;
    }
  }
}

import { OriginClient, OriginTimeoutError, PlaybackManifest } from "./originClient";
import { logger } from "./logger";

interface CachedManifest {
  manifest: PlaybackManifest;
  storedAt: number;
}

const FRESH_MS = 30_000;

export class ManifestService {
  private readonly cache = new Map<string, CachedManifest>();

  constructor(private readonly origin: OriginClient) {}

  async getManifest(assetId: string, maxBandwidth?: number): Promise<PlaybackManifest> {
    const cached = this.cache.get(assetId);
    if (cached && Date.now() - cached.storedAt < FRESH_MS) {
      return this.filter(cached.manifest, maxBandwidth);
    }

    try {
      const manifest = await this.origin.fetchManifest(assetId);
      this.cache.set(assetId, { manifest, storedAt: Date.now() });
      return this.filter(manifest, maxBandwidth);
    } catch (err) {
      if (err instanceof OriginTimeoutError && cached) {
        logger.warn("serving stale manifest after origin timeout", {
          assetId,
          ageMs: Date.now() - cached.storedAt,
        });
        return this.filter(cached.manifest, maxBandwidth);
      }
      throw err;
    }
  }

  private filter(manifest: PlaybackManifest, maxBandwidth?: number): PlaybackManifest {
    if (maxBandwidth === undefined) return manifest;
    const renditions = manifest.renditions.filter((r) => r.bandwidth <= maxBandwidth);
    return {
      ...manifest,
      renditions: renditions.length > 0 ? renditions : manifest.renditions.slice(0, 1),
    };
  }
}

import express from "express";
import { ManifestService } from "./manifestService";
import { OriginClient, OriginTimeoutError } from "./originClient";

const service = new ManifestService(new OriginClient(process.env.ORIGIN_URL ?? "http://origin.internal"));
export const router = express.Router();

router.get("/playback/:assetId/manifest", async (req, res) => {
  const maxBw = req.query.maxBandwidth ? Number(req.query.maxBandwidth) : undefined;
  try {
    const manifest = await service.getManifest(req.params.assetId, maxBw);
    res.set("cache-control", "private, max-age=10").json(manifest);
  } catch (err) {
    if (err instanceof OriginTimeoutError) {
      res.status(504).json({ error: "origin_timeout" });
      return;
    }
    res.status(502).json({ error: "origin_unavailable" });
  }
});
